"use client";
import { useState } from "react";
import toast from "react-hot-toast";
import Button from "@/components/ui/Button";
import { Clipboard, Download, Check } from "lucide-react";

interface ExportBarProps {
  summaryId: string;
  videoTitle: string;
  tldr: string;
  translatedSummary: string;
  timestampSummary: Array<{ timestamp: string; summary: string }>;
  actionItems: string[];
  category?: string;
}

export default function ExportBar({ 
  summaryId, 
  videoTitle, 
  tldr, 
  translatedSummary, 
  timestampSummary, 
  actionItems,
  category = "General Intelligence"
}: ExportBarProps) {
  const [copied, setCopied] = useState(false);
  const [pdfLoading, setPdfLoading] = useState(false);

  // Map category to display headers
  const categoryHeaders: Record<string, string> = {
    "Lectures & Tutorials": "Structured Learning Notes",
    "News & Interviews": "Key Statements & Quotes",
    "Business Content": "Strategic Business Intelligence",
    "Documentaries": "Analytical Narrative Insights",
    "General Intelligence": "Executive Summary"
  };

  const currentHeader = categoryHeaders[category] || "Executive Summary";

  const buildText = (format: "txt" | "md" = "md") => {
    const divider = format === "md" ? "---" : "--------------------------------------------------";
    const h1 = format === "md" ? "# " : "";
    const h2 = format === "md" ? "## " : "";

    const lines = [
      `${h1}${videoTitle.toUpperCase()}`,
      divider,
      "",
      `${h2}${currentHeader.toUpperCase()}`,
      tldr,
      "",
      `${h2}TRANSLATED ANALYSIS`,
      translatedSummary,
      "",
      `${h2}DEEP ANALYSIS (TIMESTAMPS)`,
      ...timestampSummary.map((k) => `[${k.timestamp}] ${k.summary}`),
      "",
      `${h2}ACTION ITEMS`,
      ...actionItems.map((a, i) => `${i + 1}. ${a}`),
      "",
      divider,
      `Generated by YT Intelligence ΓÇó ${new Date().toLocaleString()}`,
    ];
    return lines.join("\n");
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(buildText("md"));
      setCopied(true);
      toast.success("Copied to clipboard!");
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error("Failed to copy. Please try again.");
    }
  };

  const downloadFile = (content: string, extension: string) => {
    try {
      // Add UTF-8 BOM for multilingual support in Windows editors
      const blob = new Blob(["\ufeff" + content], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `${videoTitle.slice(0, 40).replace(/[^a-z0-9]/gi, "_")}_intelligence.${extension}`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      toast.success(`Report downloaded as .${extension}`);
    } catch (err) {
      console.error(err);
      toast.error("Download failed.");
    }
  };

  const handlePdf = async () => {
    // Keep PDF as requested, but warn/handle if it might fail with Unicode
    // For now, let's just make it work as best it can or favor the text download
    setPdfLoading(true);
    try {
      const { default: jsPDF } = await import("jspdf");
      const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });

      const margin = 20;
      const pageWidth = doc.internal.pageSize.getWidth();
      const maxWidth = pageWidth - margin * 2;
      let y = margin;

      const addText = (text: string, size: number, bold = false, color: [number, number, number] = [0, 0, 0]) => {
        doc.setFontSize(size);
        doc.setFont("helvetica", bold ? "bold" : "normal");
        doc.setTextColor(...color);
        const lines = doc.splitTextToSize(text, maxWidth);
        if (y + lines.length * (size * 0.4) > 280) { doc.addPage(); y = margin; }
        doc.text(lines, margin, y);
        y += lines.length * (size * 0.4) + 2;
      };

      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, pageWidth, 297, "F");

      addText("YT Intelligence Report", 22, true, [0, 0, 0]);
      y += 4;
      addText(videoTitle, 14, true, [0, 0, 0]);
      y += 8;

      addText(currentHeader.toUpperCase(), 12, true, [0, 0, 0]);
      y += 1;
      addText(tldr, 10, false, [63, 63, 70]);
      y += 6;

      if (translatedSummary) {
        addText("TRANSLATED ANALYSIS", 12, true, [0, 0, 0]);
        y += 1;
        addText(translatedSummary, 10, false, [63, 63, 70]);
        y += 6;
      }

      addText("DEEP ANALYSIS (TIMESTAMPS)", 12, true, [0, 0, 0]);
      y += 1;
      timestampSummary.forEach((k) => {
        addText(`[${k.timestamp}]`, 9, true, [0, 0, 0]);
        y -= 2;
        addText(k.summary, 9, false, [63, 63, 70]);
        y += 2;
      });
      y += 4;

      addText("ACTION ITEMS", 12, true, [0, 0, 0]);
      y += 1;
      actionItems.forEach((a, i) => addText(`${i + 1}. ${a}`, 9, false, [63, 63, 70]));

      doc.save(`${videoTitle.slice(0, 40).replace(/[^a-z0-9]/gi, "_")}_summary.pdf`);
      toast.success("PDF exported!");
    } catch (err) {
      console.error(err);
      toast.error("PDF generation failed.");
    } finally {
      setPdfLoading(false);
    }
  };

  return (
    <div className="flex items-center gap-3 flex-wrap">
      <Button
        variant="primary"
        size="sm"
        onClick={handleCopy}
        className="gap-2 h-11 px-6 rounded-xl transition-all uppercase tracking-widest text-[10px]"
      >
        {copied ? (
          <Check className="w-4 h-4" />
        ) : (
          <Clipboard className="w-4 h-4 text-muted-foreground transition-colors group-hover:text-background" />
        )}
        {copied ? "Status: Copied" : "Copy Intelligence"}
      </Button>

      <Button
        variant="primary"
        size="sm"
        onClick={() => downloadFile(buildText("txt"), "txt")}
        className="gap-2 h-11 px-6 rounded-xl transition-all uppercase tracking-widest text-[10px]"
      >
        <Download className="w-4 h-4 text-muted-foreground transition-colors group-hover:text-background" />
        Download Text (UTF-8)
      </Button>

      <Button
        variant="primary"
        size="sm"
        onClick={handlePdf}
        loading={pdfLoading}
        className="gap-2 h-11 px-6 rounded-xl transition-all uppercase tracking-widest text-[10px]"
      >
        <Download className="w-4 h-4 text-muted-foreground transition-colors group-hover:text-background" />
        Download PDF
      </Button>
    </div>
  );
}

"use client";
import { motion } from "framer-motion";

interface SentimentGaugeProps {
  score: number; // -1.0 to 1.0
  label: string; // 'positive' | 'neutral' | 'negative'
}

export default function SentimentGauge({ score, label }: SentimentGaugeProps) {
  // Score: -1 = fully negative, 0 = neutral, 1 = fully positive
  // Map score [-1, 1] ΓåÆ rotation angle [225deg, -45deg] (semicircle from left to right)
  const normalised = (score + 1) / 2; // 0 to 1
  const startAngle = 180; // far left of semicircle
  const sweepDegrees = 180;
  const rotation = startAngle - normalised * sweepDegrees; // clockwise from top

  const colors = {
    positive: "var(--foreground)",
    neutral: "var(--muted-foreground)",
    negative: "var(--border)",
  };
  const color = colors[label as keyof typeof colors] ?? colors.neutral;

  const cx = 100, cy = 100, r = 70;

  const polarToCartesian = (angle: number) => {
    const rad = ((angle - 90) * Math.PI) / 180;
    return {
      x: cx + r * Math.cos(rad),
      y: cy + r * Math.sin(rad),
    };
  };

  const start = polarToCartesian(180);
  const end = polarToCartesian(0);

  const needleAngle = 180 - normalised * 180; // 180 (left) to 0 (right)

  return (
    <div className="flex flex-col items-center gap-6">
      <svg viewBox="0 0 200 120" className="w-64 overflow-visible" role="img" aria-label={`Sentiment: ${label}`}>
        {/* Background track */}
        <path
          d={`M ${start.x} ${start.y} A ${r} ${r} 0 0 1 ${end.x} ${end.y}`}
          fill="none"
          stroke="var(--muted)"
          strokeWidth="12"
          strokeLinecap="round"
        />
        {/* Animated fill arc */}
        <motion.path
          d={`M ${start.x} ${start.y} A ${r} ${r} 0 0 1 ${end.x} ${end.y}`}
          fill="none"
          stroke={color}
          strokeWidth="12"
          strokeLinecap="round"
          strokeDasharray={`${Math.PI * r}`}
          initial={{ strokeDashoffset: Math.PI * r }}
          animate={{ strokeDashoffset: Math.PI * r * (1 - normalised) }}
          transition={{ duration: 1.5, ease: [0.16, 1, 0.3, 1] }}
          style={{ filter: "none" }}
        />
        {/* Needle */}
        <motion.line
          x1={cx}
          y1={cy}
          x2={cx + (r - 10) * Math.cos(((needleAngle - 90) * Math.PI) / 180)}
          y2={cy + (r - 10) * Math.sin(((needleAngle - 90) * Math.PI) / 180)}
          stroke={color}
          strokeWidth="2"
          strokeLinecap="round"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1, duration: 0.5 }}
        />
        <circle cx={cx} cy={cy} r="4" fill={color} />
        {/* Labels */}
        <text x="28" y="115" fill="var(--muted-foreground)" fontSize="8" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest text-[8px]">Critical</text>
        <text x="100" y="24" fill="var(--muted-foreground)" fontSize="8" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest text-[8px]">Neutral</text>
        <text x="172" y="115" fill="var(--foreground)" fontSize="8" fontWeight="bold" textAnchor="middle" className="uppercase tracking-widest text-[8px]">Positive</text>
      </svg>
      <div className="text-center">
        <div
          className="inline-flex items-center px-8 py-3 rounded-2xl border-2 transition-all duration-500 shadow-2xl"
          style={{ borderColor: color, background: label === 'positive' ? 'var(--foreground)' : 'transparent' }}
        >
          <span className="text-xs font-black uppercase tracking-[0.2em]" style={{ color: label === 'positive' ? 'var(--background)' : color }}>
            {label} Intelligence
          </span>
        </div>
        <p className="text-[10px] text-muted-foreground mt-6 font-black tracking-[0.3em] uppercase opacity-50">Signal Score: {(score >= 0 ? "+" : "") + score.toFixed(2)}</p>
      </div>
    </div>
  );
}

"use client";

import { useTheme } from "next-themes";
import { useEffect, useState } from "react";
import { Sun, Moon, Monitor } from "lucide-react";
import { cn } from "@/lib/utils";

interface ThemeToggleProps {
    className?: string;
}

export default function ThemeToggle({ className = "" }: ThemeToggleProps) {
    const { theme, setTheme } = useTheme();
    const [mounted, setMounted] = useState(false);

    useEffect(() => { setMounted(true); }, []);

    if (!mounted) return null;

    const options = [
        { value: "light", icon: Sun, label: "Light" },
        { value: "system", icon: Monitor, label: "System" },
        { value: "dark", icon: Moon, label: "Dark" },
    ];

    return (
        <div className={cn("flex items-center gap-1 rounded-lg border border-gray-200 dark:border-white/10 bg-white dark:bg-[#111] p-1 shadow-sm", className)}>
            {options.map((opt) => {
                const Icon = opt.icon;
                const isActive = theme === opt.value;
                return (
                    <button
                        key={opt.value}
                        onClick={() => setTheme(opt.value)}
                        title={opt.label}
                        className={cn(
                            "flex h-8 w-8 items-center justify-center rounded-md transition-all",
                            isActive
                                ? "bg-black text-white dark:bg-white dark:text-black shadow-sm"
                                : "text-gray-400 hover:text-black dark:text-gray-500 dark:hover:text-white"
                        )}
                    >
                        <Icon size={14} />
                    </button>
                );
            })}
        </div>
    );
}

"use client";

import { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { ArrowRight, ExternalLink } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { ShadcnButton } from "@/components/ui/shadcn-button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { cn } from "@/lib/utils";

/* ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export interface TimelineItem {
    id: number;
    title: string;
    description: string;
    status: "completed" | "in-progress" | "pending";
    icon: React.ElementType;
}

interface RadialOrbitalTimelineProps {
    timelineData: TimelineItem[];
    autoRotate?: boolean;
}

/* ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
export default function RadialOrbitalTimeline({
    timelineData,
    autoRotate = true,
}: RadialOrbitalTimelineProps) {
    const [activeNodeId, setActiveNodeId] = useState<number | null>(null);
    const [rotationAngle, setRotationAngle] = useState(0);
    const [isMobile, setIsMobile] = useState(false);
    const [hoveredId, setHoveredId] = useState<number | null>(null);

    const containerRef = useRef<HTMLDivElement>(null);
    const animRef = useRef<number>(0);
    const prevTimeRef = useRef<number>(0);
    const angleRef = useRef(0);

    /* ΓöÇΓöÇΓöÇ Responsive detection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
    useEffect(() => {
        const check = () => setIsMobile(window.innerWidth < 768);
        check();
        window.addEventListener("resize", check);
        return () => window.removeEventListener("resize", check);
    }, []);

    /* ΓöÇΓöÇΓöÇ Subtle rAF-based rotation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
    useEffect(() => {
        if (!autoRotate || isMobile || activeNodeId !== null) return;
        const tick = (timestamp: number) => {
            const delta = timestamp - prevTimeRef.current;
            prevTimeRef.current = timestamp;
            if (delta < 100) {
                // Very slow movement: ~0.05┬░ per 16ms ΓåÆ ~3┬░/s
                angleRef.current = (angleRef.current + (delta / 16) * 0.05) % 360;
                setRotationAngle(angleRef.current);
            }
            animRef.current = requestAnimationFrame(tick);
        };
        animRef.current = requestAnimationFrame(tick);
        return () => cancelAnimationFrame(animRef.current);
    }, [autoRotate, isMobile, activeNodeId]);

    const toggleItem = useCallback((id: number) => {
        setActiveNodeId(prev => (prev === id ? null : id));
    }, []);

    /* ΓöÇΓöÇΓöÇ Node positions (Memoized) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
    const nodePositions = useMemo(() => {
        const total = timelineData.length;
        const radius = isMobile ? 0 : 160; // Smaller radius for professional look
        return timelineData.map((_, index) => {
            const angle = ((index / total) * 360 + rotationAngle) % 360;
            const rad = (angle * Math.PI) / 180;
            return {
                x: radius * Math.cos(rad),
                y: radius * Math.sin(rad),
                opacity: Math.max(0.6, Math.min(1, 0.6 + 0.4 * ((1 + Math.sin(rad)) / 2))),
            };
        });
    }, [rotationAngle, timelineData, isMobile]);

    /* ΓöÇΓöÇΓöÇ MOBILE FALLBACK ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
    if (isMobile) {
        return (
            <div className="w-full space-y-3 px-4 py-8">
                {timelineData.map((item) => {
                    const Icon = item.icon;
                    const isActive = activeNodeId === item.id;
                    return (
                        <div key={item.id} className="card-minimal overflow-hidden">
                            <button
                                className="w-full flex items-center justify-between p-4 text-left"
                                onClick={() => toggleItem(item.id)}
                            >
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full border border-gray-200 bg-white flex items-center justify-center text-black shadow-sm">
                                        <Icon size={14} />
                                    </div>
                                    <div>
                                        <h4 className="text-sm font-semibold">{item.title}</h4>
                                        <p className="text-xs text-slate-500 uppercase tracking-tight">{item.status}</p>
                                    </div>
                                </div>
                                <ArrowRight className={cn("w-4 h-4 transition-transform", isActive && "rotate-90")} />
                            </button>
                            {isActive && (
                                <div className="px-4 pb-4 animate-fade-in">
                                    <p className="text-sm text-slate-600 leading-relaxed">{item.description}</p>
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        );
    }

    /* ΓöÇΓöÇΓöÇ DESKTOP ORBITAL ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
    return (
        <div
            className="relative w-full h-[600px] flex items-center justify-center bg-grid-subtle"
            ref={containerRef}
            onClick={() => setActiveNodeId(null)}
        >
            {/* Central Center Reference (SaaS Logo or Placeholder) */}
            <div className="absolute z-10 w-12 h-12 rounded-2xl bg-black flex items-center justify-center shadow-xl">
                <div className="w-4 h-4 rounded-full border-2 border-white" />
            </div>

            {/* Subtle Gray Orbit Ring */}
            <div className="absolute w-[320px] h-[320px] rounded-full border border-gray-200/50" />

            {/* Nodes */}
            {timelineData.map((item, index) => {
                const pos = nodePositions[index];
                const isActive = activeNodeId === item.id;
                const isHovered = hoveredId === item.id;
                const Icon = item.icon;

                return (
                    <div
                        key={item.id}
                        className="absolute transition-all duration-500 ease-out"
                        style={{
                            transform: `translate(${pos.x}px, ${pos.y}px)`,
                            opacity: isActive ? 1 : pos.opacity,
                            zIndex: isActive ? 50 : 20,
                        }}
                        onClick={(e) => {
                            e.stopPropagation();
                            toggleItem(item.id);
                        }}
                        onMouseEnter={() => setHoveredId(item.id)}
                        onMouseLeave={() => setHoveredId(null)}
                    >
                        {/* Node Button */}
                        <div
                            className={cn(
                                "w-10 h-10 rounded-full flex items-center justify-center border transition-all duration-300 cursor-pointer shadow-sm",
                                isActive ? "bg-black text-white border-black scale-110" : "bg-white text-black border-gray-200",
                                isHovered && !isActive && "border-gray-400 scale-105"
                            )}
                        >
                            <Icon size={16} />
                        </div>

                        {/* Label (Visible on hover or if active) */}
                        <div
                            className={cn(
                                "absolute top-12 left-1/2 -translate-x-1/2 whitespace-nowrap text-[10px] font-bold uppercase tracking-widest text-slate-500 transition-opacity",
                                (isHovered || isActive) ? "opacity-100" : "opacity-0"
                            )}
                        >
                            {item.title}
                        </div>

                        {/* Expansion Card (SaaS Style) */}
                        {isActive && (
                            <div
                                className="absolute top-20 left-1/2 -translate-x-1/2 w-64 card-minimal p-4 z-[100]"
                                style={{ animation: "cardExpand 0.2s ease-out forwards" }}
                                onClick={(e) => e.stopPropagation()}
                            >
                                <div className="flex items-center justify-between mb-2">
                                    <Badge className="badge-minimal">{item.status}</Badge>
                                </div>
                                <h3 className="text-sm font-semibold text-black mb-1">{item.title}</h3>
                                <p className="text-xs text-slate-500 leading-relaxed">{item.description}</p>
                            </div>
                        )}
                    </div>
                );
            })}
        </div>
    );
}
